import{_ as e,o,c as a,a2 as n}from"./chunks/framework.C8822HRV.js";const u=JSON.parse('{"title":"What is sdd? Spec-Driven Development CLI for AI agents","description":"sdd is a local Spec-Driven Development CLI for AI coding agents. Short plans and notes live in git so you and Copilot, Claude Code, Grok, or Ollama stay aligned—no cloud process product.","frontmatter":{"title":"What is sdd? Spec-Driven Development CLI for AI agents","description":"sdd is a local Spec-Driven Development CLI for AI coding agents. Short plans and notes live in git so you and Copilot, Claude Code, Grok, or Ollama stay aligned—no cloud process product.","head":[["meta",{"property":"og:title","content":"What is sdd? Spec-Driven Development CLI for AI agents · sdd"}],["meta",{"property":"og:description","content":"sdd is a local Spec-Driven Development CLI for AI coding agents. Short plans and notes live in git so you and Copilot, Claude Code, Grok, or Ollama stay aligned—no cloud process product."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/concepts/what-is-sdd/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"What is sdd? Spec-Driven Development CLI for AI agents · sdd"}],["meta",{"name":"twitter:description","content":"sdd is a local Spec-Driven Development CLI for AI coding agents. Short plans and notes live in git so you and Copilot, Claude Code, Grok, or Ollama stay aligned—no cloud process product."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/concepts/what-is-sdd/"}]]},"headers":[],"relativePath":"concepts/what-is-sdd.md","filePath":"concepts/what-is-sdd.md","lastUpdated":1785895617000}'),d={name:"concepts/what-is-sdd.md"};function s(r,t,i,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="what-is-sdd" tabindex="-1">What is sdd? <a class="header-anchor" href="#what-is-sdd" aria-label="Permalink to &quot;What is sdd?&quot;">​</a></h1><p>Your AI can ship a feature before lunch. By Friday, nobody remembers <em>why</em> that edge case was “fine,” what “done” meant, or what was out of scope.</p><p><strong><code>sdd</code></strong> is a <strong>Spec-Driven Development CLI</strong> you run in the terminal. It lives in your project and helps you and your <strong>AI coding agent</strong> work in <strong>short, clear steps</strong>—with notes saved <strong>in the repo</strong>, not only in a chat window.</p><p>It does <strong>not</strong> replace your stack (React, Python, …). It sits <strong>next to</strong> your code. Package: <a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer"><code>@structured-vibe-coding/cli</code></a>.</p><blockquote><p><strong>In one sentence:</strong> the AI writes; <code>sdd</code> keeps the plan and progress in git.</p></blockquote><p>For the problem story: <a href="./keep-ai-coding-in-git">Keep AI coding decisions in git</a>.</p><hr><h2 id="the-idea-in-30-seconds" tabindex="-1">The idea in 30 seconds <a class="header-anchor" href="#the-idea-in-30-seconds" aria-label="Permalink to &quot;The idea in 30 seconds&quot;">​</a></h2><ol><li>You start a piece of work (<code>sdd new</code> or <code>sdd greenfield</code>).</li><li>You (or the AI) fill a short markdown file.</li><li>You run <code>sdd next</code> when that step is done.</li><li>You write code, check it, and run <code>sdd complete</code>.</li></ol><p>Everything for that work sits in a folder under <code>changes/</code>. Longer-lived product notes can live under <code>memory/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You decide what to build     sdd tracks the steps      AI helps write notes &amp; code</span></span>
<span class="line"><span>           │                          │                           │</span></span>
<span class="line"><span>           ▼                          ▼                           ▼</span></span>
<span class="line"><span>     sdd new &quot;…&quot;  →  edit a short file  →  sdd next  →  code  →  done</span></span></code></pre></div><hr><h2 id="words-you-ll-see-plain-english" tabindex="-1">Words you’ll see (plain English) <a class="header-anchor" href="#words-you-ll-see-plain-english" aria-label="Permalink to &quot;Words you’ll see (plain English)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Change pack</strong></td><td>One folder for <em>this</em> task or PR (<code>changes/…</code>)</td></tr><tr><td><strong>Stage</strong></td><td>One step on the path (e.g. “describe the fix”, then “code”, then “check”)</td></tr><tr><td><strong>Workflow</strong></td><td>Which path of stages you use (short fix vs feature vs new product)</td></tr><tr><td><strong>Memory</strong></td><td>Stable notes about the product (<code>memory/</code>) that last beyond one PR</td></tr><tr><td><strong>Agent</strong></td><td>Your AI coding tool (Copilot, Grok, Claude, Ollama) — not your editor</td></tr></tbody></table><hr><h2 id="who-does-what" tabindex="-1">Who does what <a class="header-anchor" href="#who-does-what" aria-label="Permalink to &quot;Who does what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Who</th><th>Job</th></tr></thead><tbody><tr><td><strong>You</strong></td><td>Decide scope, quality, and when to move on</td></tr><tr><td><strong><code>sdd</code></strong></td><td>Remember the step, create files, show status</td></tr><tr><td><strong>AI</strong></td><td>Draft notes and write code when you want help</td></tr><tr><td><strong>Your editor</strong></td><td>Edit files (no special plugin required)</td></tr></tbody></table><hr><h2 id="pick-a-path-by-situation" tabindex="-1">Pick a path by situation <a class="header-anchor" href="#pick-a-path-by-situation" aria-label="Permalink to &quot;Pick a path by situation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Start with</th></tr></thead><tbody><tr><td>Small bug or typo</td><td><code>sdd new &quot;…&quot; -w hotfix</code></td></tr><tr><td>Normal feature</td><td><code>sdd new &quot;…&quot; -w feature</code></td></tr><tr><td>Brand-new product</td><td><code>sdd greenfield &quot;one-line idea&quot;</code></td></tr><tr><td>Big / multi-team change</td><td><code>sdd new &quot;…&quot; -w enterprise-feature</code></td></tr></tbody></table><hr><h2 id="what-it-is-not" tabindex="-1">What it is <em>not</em> <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is *not*&quot;">​</a></h2><ul><li>Not a required VS Code or IntelliJ extension</li><li>Not a cloud “process product” you must log into</li><li>Not a replacement for Jira or Git</li><li>Not “install every AI at once” — you pick <strong>one</strong> when you run <code>sdd init</code></li></ul><hr><h2 id="best-next-step" tabindex="-1">Best next step <a class="header-anchor" href="#best-next-step" aria-label="Permalink to &quot;Best next step&quot;">​</a></h2><p>Don’t over-read. Run one tiny loop:</p><p><strong>→ <a href="./../tutorials/first-change">Start in 10 minutes</a></strong></p><p>Want the “why”? → <a href="./why-sdd">Why sdd exists</a></p>`,28)])])}const g=e(d,[["render",s]]);export{u as __pageData,g as default};
